package com.interview.mysqlescdc.verifier.rebuild;
import static org.assertj.core.api.Assertions.*;import java.sql.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.*;import org.springframework.jdbc.core.simple.JdbcClient;import org.springframework.jdbc.datasource.*;import com.interview.mysqlescdc.verifier.source.*;
class JdbcConsistentSourceScannerIT {
 static final long BASE=981000;JdbcClient root;JdbcConsistentSourceScanner scanner;
 @BeforeEach void setup(){root=JdbcClient.create(new DriverManagerDataSource(url(),"root","rootpass"));scanner=new JdbcConsistentSourceScanner(new DriverManagerDataSource(url(),"verifier","verifierpass"),new IndependentExpectedProjector());cleanup();root.sql("INSERT INTO categories(id,name) VALUES(:id,'Original category')").param("id",BASE).update();for(int i=1;i<=4;i++){long id=BASE+i;root.sql("INSERT INTO products(id,sku,name,description,category_id,price_cents,status) VALUES(:id,:sku,:name,'d',:category,100,'ACTIVE')").param("id",id).param("sku","SNAP-"+id).param("name","Original "+i).param("category",BASE).update();root.sql("INSERT INTO inventory(product_id,available_quantity,reserved_quantity) VALUES(:id,5,0)").param("id",id).update();root.sql("INSERT INTO product_search_revision(product_id,revision,active,updated_at) VALUES(:id,1,TRUE,'2026-07-28 10:00:00.123456')").param("id",id).update();}}
 @AfterEach void cleanup(){root.sql("DELETE FROM product_search_revision WHERE product_id BETWEEN :a AND :b").param("a",BASE).param("b",BASE+10).update();root.sql("DELETE FROM inventory WHERE product_id BETWEEN :a AND :b").param("a",BASE).param("b",BASE+10).update();root.sql("DELETE FROM products WHERE id BETWEEN :a AND :b").param("a",BASE).param("b",BASE+10).update();root.sql("DELETE FROM categories WHERE id=:id").param("id",BASE).update();}
 @Test void one_connection_repeatable_read_snapshot_excludes_concurrent_changes(){Map<Long,ExpectedDocument> observed=new LinkedHashMap<>();try(var cursor=scanner.open()){long after=0;boolean mutated=false;while(true){var page=cursor.readAfter(after,2);page.documents().forEach(d->{if(d.productId()>BASE&&d.productId()<=BASE+10)observed.put(d.productId(),d);});if(!mutated&&observed.keySet().stream().anyMatch(id->id==BASE+1)){mutate();mutated=true;}if(page.complete())break;after=page.nextExclusiveProductId();}}assertThat(observed.keySet()).contains(BASE+1,BASE+2,BASE+3,BASE+4).doesNotContain(BASE+5);assertThat(observed.get(BASE+1).name()).isEqualTo("Original 1");assertThat(observed.get(BASE+1).sourceRevision()).isEqualTo(1);assertThat(observed.get(BASE+2).searchable()).isTrue();try(var fresh=scanner.open()){Map<Long,ExpectedDocument> now=scan(fresh);assertThat(now.get(BASE+1).name()).isEqualTo("Renamed");assertThat(now.get(BASE+1).sourceRevision()).isEqualTo(2);assertThat(now.get(BASE+2).searchable()).isFalse();assertThat(now).containsKey(BASE+5);}}
 @Test void bounds_open_snapshots_at_four_and_releases_permit_on_close(){var cursors=new ArrayList<SourceSnapshotCursor>();try{for(int i=0;i<4;i++)cursors.add(scanner.open());assertThatThrownBy(scanner::open).isInstanceOf(IllegalStateException.class).hasMessageContaining("too many");cursors.removeFirst().close();cursors.add(scanner.open());}finally{cursors.forEach(SourceSnapshotCursor::close);}}
 @Test void incomplete_active_aggregate_fails_closed_and_auto_closes_cursor(){long id=BASE+6;root.sql("INSERT INTO products(id,sku,name,description,category_id,price_cents,status) VALUES(:id,:sku,'Incomplete','d',:category,100,'ACTIVE')").param("id",id).param("sku","SNAP-"+id).param("category",BASE).update();root.sql("INSERT INTO product_search_revision(product_id,revision,active) VALUES(:id,1,TRUE)").param("id",id).update();var cursor=scanner.open();assertThatThrownBy(()->cursor.readAfter(0,200)).isInstanceOf(IllegalStateException.class).hasMessageContaining("business aggregate is absent");assertThatThrownBy(()->cursor.readAfter(0,200)).isInstanceOf(IllegalStateException.class).hasMessageContaining("closed");}
 @Test void two_concurrent_cursors_keep_independent_old_snapshots(){try(var first=scanner.open();var second=scanner.open()){first.readAfter(0,1);second.readAfter(0,1);mutate();assertThat(scan(first).get(BASE+1).name()).isEqualTo("Original 1");assertThat(scan(second).get(BASE+1).name()).isEqualTo("Original 1");}try(var fresh=scanner.open()){assertThat(scan(fresh).get(BASE+1).name()).isEqualTo("Renamed");}}
 @Test void every_page_uses_one_physical_connection(){var counted=new CountingDataSource(new DriverManagerDataSource(url(),"verifier","verifierpass"));var one=new JdbcConsistentSourceScanner(counted,new IndependentExpectedProjector());try(var cursor=one.open()){var first=cursor.readAfter(0,1);cursor.readAfter(first.nextExclusiveProductId(),1);}assertThat(counted.acquisitions).hasValue(1);}
 @Test void dedicated_cursor_has_exact_zero_one_two_hundred_two_hundred_one_and_two_hundred_five_boundaries(){root.sql("UPDATE categories SET updated_at='2026-07-28 14:00:00.123456' WHERE id=:id").param("id",BASE).update();for(int total:new int[]{0,1,200,201,205}){long base=root.sql("SELECT COALESCE(MAX(product_id),0)+1000 FROM product_search_revision").query(Long.class).single();try{for(int i=1;i<=total;i++){long id=base+i;root.sql("INSERT INTO products(id,sku,name,description,category_id,price_cents,status,updated_at) VALUES(:id,:sku,:name,'boundary',:category,100,'ACTIVE','2026-07-28 14:00:00.123456')").param("id",id).param("sku","BOUND-"+id).param("name","Boundary "+id).param("category",BASE).update();root.sql("INSERT INTO inventory(product_id,available_quantity,reserved_quantity,updated_at) VALUES(:id,5,0,'2026-07-28 14:00:00.123456')").param("id",id).update();root.sql("INSERT INTO product_search_revision(product_id,revision,active,updated_at) VALUES(:id,:revision,TRUE,'2026-07-28 14:00:00.123456')").param("id",id).param("revision",i+1).update();}List<Integer> sizes=new ArrayList<>();List<Long> tokens=new ArrayList<>();List<ExpectedDocument> docs=new ArrayList<>();try(var cursor=scanner.open()){long after=base;while(true){var page=cursor.readAfter(after,200);sizes.add(page.documents().size());tokens.add(page.nextExclusiveProductId());docs.addAll(page.documents());if(page.complete())break;after=page.nextExclusiveProductId();}}if(total==201){assertThat(sizes).containsExactly(200,1);assertThat(tokens).containsExactly(base+200,base+201);}else if(total==205){assertThat(sizes).containsExactly(200,5);assertThat(tokens).containsExactly(base+200,base+205);}else{assertThat(sizes).containsExactly(total);assertThat(tokens).containsExactly(base+total);}assertThat(docs).hasSize(total);if(total>0){assertThat(docs.getFirst().sourceRevision()).isEqualTo(2);assertThat(docs.getLast().sourceRevision()).isEqualTo(total+1);assertThat(docs).allSatisfy(d->assertThat(d.sourceUpdatedAt()).isEqualTo(java.time.Instant.parse("2026-07-28T14:00:00.123456Z")));}}finally{root.sql("DELETE FROM product_search_revision WHERE product_id BETWEEN :a AND :b").param("a",base+1).param("b",base+total).update();root.sql("DELETE FROM inventory WHERE product_id BETWEEN :a AND :b").param("a",base+1).param("b",base+total).update();root.sql("DELETE FROM products WHERE id BETWEEN :a AND :b").param("a",base+1).param("b",base+total).update();}}}
 private void mutate(){root.sql("UPDATE products SET name='Renamed' WHERE id=:id").param("id",BASE+1).update();root.sql("UPDATE product_search_revision SET revision=2,updated_at='2026-07-28 10:01:00.654321' WHERE product_id=:id").param("id",BASE+1).update();root.sql("UPDATE product_search_revision SET revision=2,active=FALSE WHERE product_id=:id").param("id",BASE+2).update();long id=BASE+5;root.sql("INSERT INTO products(id,sku,name,description,category_id,price_cents,status) VALUES(:id,:sku,'New','d',:category,100,'ACTIVE')").param("id",id).param("sku","SNAP-"+id).param("category",BASE).update();root.sql("INSERT INTO inventory(product_id,available_quantity,reserved_quantity) VALUES(:id,5,0)").param("id",id).update();root.sql("INSERT INTO product_search_revision(product_id,revision,active) VALUES(:id,1,TRUE)").param("id",id).update();}
 private Map<Long,ExpectedDocument> scan(SourceSnapshotCursor c){Map<Long,ExpectedDocument> out=new HashMap<>();long after=0;while(true){var p=c.readAfter(after,200);p.documents().forEach(d->{if(d.productId()>BASE&&d.productId()<=BASE+10)out.put(d.productId(),d);});if(p.complete())return out;after=p.nextExclusiveProductId();}}
 private static String url(){return "jdbc:mysql://127.0.0.1:3308/product_catalog?useSSL=false&allowPublicKeyRetrieval=true&serverTimezone=UTC";}
 private static final class CountingDataSource extends AbstractDataSource{private final DriverManagerDataSource delegate;private final AtomicInteger acquisitions=new AtomicInteger();private CountingDataSource(DriverManagerDataSource delegate){this.delegate=delegate;}public Connection getConnection()throws SQLException{acquisitions.incrementAndGet();return delegate.getConnection();}public Connection getConnection(String user,String password)throws SQLException{acquisitions.incrementAndGet();return delegate.getConnection(user,password);}}
}
